function callScript() {
    try {
        CASLogger.debug("Inside Workflow script: Aria Automation Request Workflow.");
        var request = new CSRequestUtil();
        var result = request.requestCatalog(current);
        if (result.state == '4') {
            current.state = '4';
            current.comments = result.comments;
            //c
        } else {
            current.state = result.state;
            current.comments = result.comments;
            //c
        }
    } catch (e) {
        CASLogger.error("Exception caught Inside Workflow script: Aria Automation Request Workflow: " + e);
    }
}

