answer = ifScript();
function ifScript() {
	if(current.cat_item.organisation_name.select_automation_service == 'vrealizeAutomationService')
	{
		//gs.addInfoMessage('vRA Catalog Item Requested');
		//CASLogger.info('vRA Catalog Item Requested');
		return 'yes';
	}
	else
	{
		return 'no';
	}
}

// This script needs to set answer to 'yes' or 'no' to indicate the state of the activity.
//
// For example,
//
//   answer = ifScript();
//
//   function ifScript() {
//      if (condition is true) {
//         return 'yes';
//      }
//      return 'no';
//   }
var casUtil = new CASAppUtil();
var snOnPrem = gs.getProperty(casUtil.configuration.properties.sn_onprem);
if (snOnPrem == 'false' || snOnPrem === false) {

    var status = current.cat_item.organisation_name.mid_server.status;
    var midserver = current.cat_item.organisation_name.mid_server.name;

    //CASLogger.info('Mid Server status is ' + status + ' while catalog item is requested with RITM Number ' + current.number);

    var casUtil = new CASAppUtil();
    var cluster = (gs.getProperty(casUtil.configuration.properties.cluster_routing)).toLowerCase();

    if (cluster == 'true' || cluster == true) {
        var isAnyMidServerUp = false;
        var clusterMIDServerGR = new GlideRecord(casUtil.configuration.table.cluster_member);
        clusterMIDServerGR.addQuery('agent.name', midserver);
        clusterMIDServerGR.query();

        while (clusterMIDServerGR.next()) {
            var clusterSysID = clusterMIDServerGR.cluster;
            var clusterMIDServerStatusGR = new GlideRecord(casUtil.configuration.table.cluster_member);
            clusterMIDServerStatusGR.addQuery('cluster', clusterSysID);
            clusterMIDServerStatusGR.query();

            while (clusterMIDServerStatusGR.next()) {
                var midServerStatus = clusterMIDServerStatusGR.agent.status.getDisplayValue();
                if (midServerStatus == 'Up') {
                    isAnyMidServerUp = true;
                }
            }
        }
        if (isAnyMidServerUp) {
            CASLogger.debug("Inside Check MidServer of Request Workflow: The MidServer utilizes the cluster routing mechanism.");
            answer = 'yes';
        } else {
            CASLogger.error('Inside Check MidServer of Request Workflow: All mid-servers across all clusters are down. Correct the Mid Server Status and perform the operation again.');
            workflow.scratchpad.midserver_msg = 'All mid-servers across all clusters are down. Correct the Mid Server Status and perform the operation again';
            answer = 'no';
        }
    } else if (status == 'Up') {
        answer = 'yes';
    } else {
        workflow.scratchpad.midserver_msg = 'Mid Server name: ' + midserver + ' status is: ' + status;
        answer = 'no';
    }
} else {
    answer = 'yes';
}

// This script needs to set answer to 'yes' or 'no' to indicate the state of the activity.
//
// For example,
//
//   answer = ifScript();
//
//   function ifScript() {
//      if (condition is true) {
//         return 'yes';
//      }
//      return 'no';
//   }
var casUtil = new CASAppUtil();
var snOnPrem = gs.getProperty(casUtil.configuration.properties.sn_onprem);
if (snOnPrem == 'false' || snOnPrem === false) {

    var status = current.cat_item.organisation_name.mid_server.status;
    var midserver = current.cat_item.organisation_name.mid_server.name;

    //CASLogger.info('Mid Server status is ' + status + ' while catalog item is requested with RITM Number ' + current.number);

    var casUtil = new CASAppUtil();
    var cluster = (gs.getProperty(casUtil.configuration.properties.cluster_routing)).toLowerCase();

    if (cluster == 'true' || cluster == true) {
        var isAnyMidServerUp = false;
        var clusterMIDServerGR = new GlideRecord(casUtil.configuration.table.cluster_member);
        clusterMIDServerGR.addQuery('agent.name', midserver);
        clusterMIDServerGR.query();

        while (clusterMIDServerGR.next()) {
            var clusterSysID = clusterMIDServerGR.cluster;
            var clusterMIDServerStatusGR = new GlideRecord(casUtil.configuration.table.cluster_member);
            clusterMIDServerStatusGR.addQuery('cluster', clusterSysID);
            clusterMIDServerStatusGR.query();

            while (clusterMIDServerStatusGR.next()) {
                var midServerStatus = clusterMIDServerStatusGR.agent.status.getDisplayValue();
                if (midServerStatus == 'Up') {
                    isAnyMidServerUp = true;
                }
            }
        }
        if (isAnyMidServerUp) {
            CASLogger.debug("Inside Check MidServer of Request Workflow: The MidServer utilizes the cluster routing mechanism.");
            answer = 'yes';
        } else {
            CASLogger.error('Inside Check MidServer of Request Workflow: All mid-servers across all clusters are down. Correct the Mid Server Status and perform the operation again.');
            workflow.scratchpad.midserver_msg = 'All mid-servers across all clusters are down. Correct the Mid Server Status and perform the operation again';
            answer = 'no';
        }
    } else if (status == 'Up') {
        answer = 'yes';
    } else {
        workflow.scratchpad.midserver_msg = 'Mid Server name: ' + midserver + ' status is: ' + status;
        answer = 'no';
    }
} else {
    answer = 'yes';
}

